'use strict';

// MODULES //

var tape = require( 'tape' );
var isndarrayLike = require( '@stdlib/assert/is-ndarray-like' );
var isReadOnly = require( '@stdlib/ndarray/base/assert/is-read-only' );
var zeroTo = require( '@stdlib/array/base/zero-to' );
var typedarray = require( '@stdlib/array/typed' );
var ndarray2array = require( '@stdlib/ndarray/to-array' );
var ctor = require( '@stdlib/ndarray/ctor' );
var pop = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof pop, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns an array containing ndarrays (ndims=1, strict, readonly)', function test( t ) {
	var actual;
	var buf;
	var ord;
	var sh;
	var st;
	var o;
	var x;

	buf = typedarray( zeroTo( 6 ), 'float64' );
	sh = [ 6 ];
	st = [ 1 ];
	o = 0;
	ord = 'row-major';

	x = new ctor( 'float64', buf, sh, st, o, ord );

	actual = pop( x, 0, true, false );

	t.strictEqual( isndarrayLike( actual[0] ), true, 'returns expected value' );
	t.strictEqual( isndarrayLike( actual[1] ), true, 'returns expected value' );
	t.strictEqual( isReadOnly( actual[0] ), true, 'returns expected value' );
	t.strictEqual( isReadOnly( actual[1] ), true, 'returns expected value' );
	t.strictEqual( actual[0].ndims, 1, 'returns expected value' );
	t.strictEqual( actual[1].ndims, 1, 'returns expected value' );
	t.strictEqual( actual[0].length, 5, 'returns expected value' );
	t.strictEqual( actual[1].length, 1, 'returns expected value' );
	t.deepEqual( ndarray2array( actual[0] ), [ 0, 1, 2, 3, 4 ], 'returns expected value' );
	t.deepEqual( ndarray2array( actual[1] ), [ 5 ], 'returns expected value' );

	t.end();
});

