tape( 'the function returns an array containing ndarrays (ndims=2, strict, readonly)', function test( t ) {
	var actual;
	var buf;
	var ord;
	var sh;
	var st;
	var o;
	var x;

	buf = typedarray( zeroTo( 8 ), 'float64' );
	sh = [ 2, 4 ];
	st = [ 4, 1 ];
	o = 0;
	ord = 'row-major';

	x = new ctor( 'float64', buf, sh, st, o, ord );

	actual = pop( x, 0, true, false );

	t.strictEqual( isndarrayLike( actual[0] ), true, 'returns expected value' );
	t.strictEqual( isndarrayLike( actual[1] ), true, 'returns expected value' );
	t.strictEqual( isReadOnly( actual[0] ), true, 'returns expected value' );
	t.strictEqual( isReadOnly( actual[1] ), true, 'returns expected value' );
	t.strictEqual( actual[0].ndims, 2, 'returns expected value' );
	t.strictEqual( actual[1].ndims, 2, 'returns expected value' );
	t.strictEqual( actual[0].length, 4, 'returns expected value' );
	t.strictEqual( actual[1].length, 4, 'returns expected value' );
	t.deepEqual( ndarray2array( actual[0] ), [ [ 0, 1, 2, 3 ] ], 'returns expected value' );
	t.deepEqual( ndarray2array( actual[1] ), [ [ 4, 5, 6, 7 ] ], 'returns expected value' );

	t.end();
});

