tape( 'the function returns an array containing ndarrays (ndims=3, strict, readonly)', function test( t ) {
	var actual;
	var buf;
	var ord;
	var sh;
	var st;
	var o;
	var x;

	buf = typedarray( zeroTo( 8 ), 'float64' );
	sh = [ 2, 2, 2 ];
	st = [ 4, 2, 1 ];
	o = 0;
	ord = 'row-major';

	/*
	* [
	*   [
	*     [ 0, 1 ],
	*     [ 2, 3 ]
	*   ],
	*   [
	*     [ 4, 5 ],
	*     [ 6, 7 ]
	*   ]
	*];
	*/
	x = new ctor( 'float64', buf, sh, st, o, ord );

	actual = pop( x, 1, true, false );

	t.strictEqual( isndarrayLike( actual[0] ), true, 'returns expected value' );
	t.strictEqual( isndarrayLike( actual[1] ), true, 'returns expected value' );
	t.strictEqual( isReadOnly( actual[0] ), true, 'returns expected value' );
	t.strictEqual( isReadOnly( actual[1] ), true, 'returns expected value' );
	t.strictEqual( actual[0].ndims, 3, 'returns expected value' );
	t.strictEqual( actual[1].ndims, 3, 'returns expected value' );
	t.strictEqual( actual[0].length, 4, 'returns expected value' );
	t.strictEqual( actual[1].length, 4, 'returns expected value' );
	t.deepEqual( ndarray2array( actual[0] ), [ [ [ 0, 1 ] ], [ [ 4, 5 ] ] ], 'returns expected value' );
	t.deepEqual( ndarray2array( actual[1] ), [ [ [ 2, 3 ] ], [ [ 6, 7 ] ] ], 'returns expected value' );

	t.end();
});

